/**
 * freq_div.v
 *
 * Frequency Divider Module - Fully Modular Clock Divider Implementation
 *
 * Inputs:
 *   CLK_in - 100 MHz input clock
 *   RST    - Asynchronous active-high reset
 *
 * Outputs:
 *   CLK_50 - 50 MHz clock output (CLK_in / 2)
 *   CLK_10 - 10 MHz clock output (CLK_in / 10)
 *   CLK_1  -  1 MHz clock output (CLK_in / 100)
 *
 * Implementation:
 *   - CLK_50 toggled every rising edge of CLK_in or reset in a dedicated always block.
 *   - CLK_10 generated by a 3-bit counter that toggles CLK_10 every 5 CLK_in cycles.
 *   - CLK_1 generated by a 6-bit counter that toggles CLK_1 every 50 CLK_in cycles.
 *   - Separate always blocks for each clock output to isolate toggle paths.
 *   - Asynchronous active-high reset resets clocks and counters.
 */

module freq_div (
    input  wire CLK_in,
    input  wire RST,
    output reg  CLK_50,
    output reg  CLK_10,
    output reg  CLK_1
);

    // Counter for CLK_10: counts 0 to 4 for divide by 10 (toggle every 5 cycles)
    reg [2:0] cnt_10;
    // Counter for CLK_1: counts 0 to 49 for divide by 100 (toggle every 50 cycles)
    reg [5:0] cnt_100;

    // CLK_50 generation: toggle every clock cycle -> frequency division by 2
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_50 <= 1'b0;
        end else begin
            CLK_50 <= ~CLK_50;
        end
    end

    // CLK_10 generation: toggle CLK_10 every 5 clock cycles (count 0 to 4)
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_10 <= 3'd0;
            CLK_10 <= 1'b0;
        end else begin
            if (cnt_10 == 3'd4) begin
                cnt_10 <= 3'd0;
                CLK_10 <= ~CLK_10;
            end else begin
                cnt_10 <= cnt_10 + 1'b1;
            end
        end
    end

    // CLK_1 generation: toggle CLK_1 every 50 clock cycles (count 0 to 49)
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_100 <= 6'd0;
            CLK_1 <= 1'b0;
        end else begin
            if (cnt_100 == 6'd49) begin
                cnt_100 <= 6'd0;
                CLK_1 <= ~CLK_1;
            end else begin
                cnt_100 <= cnt_100 + 1'b1;
            end
        end
    end

endmodule